#!/usr/bin/env python3
"""Exact legal-fleet enumerator and posterior helper for the 5x5 game."""
from __future__ import annotations

import argparse
from collections import Counter
from functools import lru_cache
from itertools import combinations

N = 5
LENGTHS = (3, 2, 2, 1, 1)
CELLS = tuple(f"{chr(65 + c)}{r + 1}" for r in range(N) for c in range(N))
INDEX = {cell: i for i, cell in enumerate(CELLS)}
FULL = (1 << (N * N)) - 1


def bit(cell: str) -> int:
    return 1 << INDEX[cell]


def neighbours(i: int) -> int:
    r, c = divmod(i, N)
    out = 0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            rr, cc = r + dr, c + dc
            if 0 <= rr < N and 0 <= cc < N:
                out |= 1 << (rr * N + cc)
    return out


HALOS = tuple(neighbours(i) for i in range(N * N))


def halo(mask: int) -> int:
    out = 0
    while mask:
        low = mask & -mask
        out |= HALOS[low.bit_length() - 1]
        mask ^= low
    return out


@lru_cache(None)
def placements(length: int) -> tuple[tuple[int, int], ...]:
    """Return (ship mask, halo mask) pairs, in a deterministic order."""
    ans = []
    for r in range(N):
        for c in range(N):
            for dr, dc in ((0, 1), (1, 0)):
                if length == 1 and (dr, dc) != (0, 1):
                    continue
                cells = []
                for k in range(length):
                    rr, cc = r + dr * k, c + dc * k
                    if not (0 <= rr < N and 0 <= cc < N):
                        break
                    cells.append(rr * N + cc)
                if len(cells) == length:
                    mask = sum(1 << i for i in cells)
                    ans.append((mask, halo(mask)))
    return tuple(ans)


def enumerate_fleets() -> tuple[tuple[int, ...], ...]:
    fleets = []

    def rec(k: int, start: int, occupied: int, blocked: int, chosen: tuple[int, ...]):
        if k == len(LENGTHS):
            fleets.append(chosen)
            return
        length = LENGTHS[k]
        ps = placements(length)
        # Equal-length ships are unordered; impose increasing placement indices.
        for j in range(start, len(ps)):
            mask, h = ps[j]
            if mask & blocked:
                continue
            next_start = j + 1 if k + 1 < len(LENGTHS) and LENGTHS[k + 1] == length else 0
            rec(k + 1, next_start, occupied | mask, blocked | h, chosen + (mask,))

    rec(0, 0, 0, 0, ())
    return tuple(fleets)


FLEETS = enumerate_fleets()
SHIP_OF_CELL = []
for i in range(N * N):
    SHIP_OF_CELL.append(tuple((fi, si) for fi, fleet in enumerate(FLEETS) for si, ship in enumerate(fleet) if ship & (1 << i)))


def mask_cells(mask: int) -> list[str]:
    return [CELLS[i] for i in range(N * N) if mask & (1 << i)]


def occupied(fleet: tuple[int, ...]) -> int:
    out = 0
    for ship in fleet:
        out |= ship
    return out


OCCUPIED = tuple(occupied(f) for f in FLEETS)


def compatible(fleet: tuple[int, ...], shots: list[tuple[str, str, int | None]]) -> bool:
    """Check exact chronological shot results against a fleet.

    Each shot is (cell, result, sunk_length), where result is miss/hit/sunk.
    """
    targets = []
    for cell, result, sunk_length in shots:
        targets.append(cell)
        m = bit(cell)
        ship = next((s for s in fleet if s & m), 0)
        if not ship:
            if result != "miss":
                return False
            continue
        if result == "miss":
            return False
        ship_cells = mask_cells(ship)
        is_sunk = all(c in targets for c in ship_cells)
        if is_sunk:
            if result != "sunk" or sunk_length != len(ship_cells):
                return False
        elif result != "hit":
            return False
    return True


def posterior(shots: list[tuple[str, str, int | None]]) -> list[tuple[int, ...]]:
    return [fleet for fleet in FLEETS if compatible(fleet, shots)]


def parse_log(text: str) -> list[tuple[str, str, int | None]]:
    # Comma-separated entries such as A1:miss,B2:hit,C3:sunk:2
    shots = []
    if not text:
        return shots
    for entry in text.split(","):
        fields = entry.split(":")
        shots.append((fields[0].upper(), fields[1], int(fields[2]) if len(fields) > 2 else None))
    return shots


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--log", default="", help="shot log: A1:miss,B2:hit,C3:sunk:2")
    parser.add_argument("--summary", action="store_true")
    args = parser.parse_args()
    print(f"legal fleets: {len(FLEETS)}")
    if args.summary or not args.log:
        counts = [sum(bool(occ & (1 << i)) for occ in OCCUPIED) for i in range(N * N)]
        print("Uniform-prior ship-cell probabilities (percent):")
        for r in range(N):
            print(" ".join(f"{100 * counts[r*N+c] / len(FLEETS):6.2f}" for c in range(N)))
        print("Cell ranking, low to high:")
        print(" ".join(CELLS[i] for i in sorted(range(N*N), key=lambda i: (counts[i], i))))
        return
    shots = parse_log(args.log)
    post = posterior(shots)
    print(f"posterior fleets: {len(post)}")
    if not post:
        return
    already = {s[0] for s in shots}
    options = []
    for i, cell in enumerate(CELLS):
        if cell in already:
            continue
        hit_fleets = [f for f in post if occupied(f) & (1 << i)]
        if not hit_fleets:
            p_hit = p_sunk = 0.0
        else:
            p_hit = len(hit_fleets) / len(post)
            n_sunk = 0
            for f in hit_fleets:
                ship = next(s for s in f if s & (1 << i))
                others = [c for c in mask_cells(ship) if c != cell]
                if all(c in already for c in others):
                    n_sunk += 1
            p_sunk = n_sunk / len(post)
        options.append((p_hit, p_sunk, cell))
    for p_hit, p_sunk, cell in sorted(options, reverse=True):
        print(f"{cell}: hit {p_hit:.5f}, immediate sunk {p_sunk:.5f}")


if __name__ == "__main__":
    main()
